INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_SOURCE_ASSET_ID','Source system  from where the asset information is derived followed by a sequential number could be an option. E.G FNT 0001 VEED 0000001 - 9999999 LCM 0001 Once the asset logs have been baselined then we will derive','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_NAME','Asset Name May be hostname (see 7.02) or an individual assets name The asset management tool will hold assets that are in scope and out of scope of TSR The definition of an in scope TSR asset is: Equipment and/or software which forms part of the PECN/PECS or which is connected with the operation of the PECN/PECS. If the asset is in scope of TSR then either the PECN or PECS fields must be completed','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_DESCRIPTION','Text description of the asset free text as long as it can be automated in the future to reduce manual overhead In the future we could look at a description look up table based on the asset Name to remove manual overhead','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_TYPE','Hardware - physical, virtual, Software - application, database, website, if its a software asset type then there would be no hardware related attributes completed In the future we could look at a description look up table based on the asset Name to remove manual overhead ','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('BUSINESS_OWNER','Name of the Business owner e.g. product owner - account manager etc','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('SUPPORT_OWNER','Name of the support owner e.g. Andy Boone / Trevor Bryan In the future we could create a Support look-up config table based on the Network Level. We would default to unknown if we could not find the persons name','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('SUPPORT_TEAM','The support team in which the support owner resides Look at org chart for Dept In the future we could create a Support look-up config table based on the Network Level. We would default to unknown if we could not find the Support Team','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('SUPPORT_DOMAIN','Refer to org chart In the future we could create a Support look-up config table based on the Network Level. We would default to unknown if we could not find the Organisation placement','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_SERVICE_TYPE',' e.g. Network element, OSS-VFUK EIT-INFOVISTA etc For Networks it will be either Network Element or for OSS it will be OSS-<ServiceName in Totuus> In the future we will be able to derive from the data source of the asset','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_DEPLOYMENT_STATUS','This is the status of the asset within the standard Life cycle management definitions','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('RISK_ID','Only accepted risk id(s) single id or multiple ids delimited with a commaat the moment this is humanised data if known LEAVE THIS BLANK AS DEFINITIONS TO BE ADVISED requested change to Synergi','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('REGULATORY_SCOPE','GDPR, Telecom Security Act (TSA), etc All network assets are TSA as we are declaring all networks assets in scope so default is TSA If an asset has personal data element then it would be GDPR not limited to TSA and GDPR please put all regulatory acronyms that apply If multiple entries then delimit with a comma.','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_COUNTRY_LOCATED','Normal short codes for a country','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('GEO_LOCATION','Geographical site / cloud zone using agreed unique location ID If the asset is an EXPOSED edge asset then where possible please use the MOIRE Code (also known as Short Code and 333-Code) to describe the Geo Location If you do not use MOIRE codes then please use your usual description of locations (e.g. site address) OR cloud zone using agreed unique location ID N.B if the asset is not an exposed edge asset then please use the location that you currently use Also see Geolocation TAB ','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('INFRASTRUCTURE LOCATION','The functional location is where abouts the device lives within the Vodafone network areas. These are as follows:- • Exposed Edge •	Customer premises equipment •	Aggregation/access • Provider edge •	Optical Core • Mobile Core • Data Core •	Management LAN • Session Access Zone • Development / lab In the future we may be able to use some data from Cramer?','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('UPSTREAM_DEPENDENCIES','Document any way of identifying a dependency e.g. for a PE or CE router the method of identifying an interdependency could be the circuit reference that links the 2 devices','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('DOWNSTREAM_DEPENDENCIES','Document any way of identifying a dependency e.g. for a PE or CE router the method of identifying an interdependency could be the circuit reference that links the 2 devices','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('CHANGE_DESCRIPTION','This the CRQ references and the dates of the CRQs raised against the asset, specific to a change or upgrade to the asset, if this information is readily available if not put unknown','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('IS_CLOUD_HOSTED','Humanised data or may be in data source','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('CLOUD_TYPE','Humanised data In the future we may be able to populate from data source','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('CLOUD_VENDOR','Humanised data In the future we may be able to populate from data source e.g. aws should be amazon','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('EQUIPMENT_NAME',' This is either the MAC Address or the server name , the server name may in some instances be the same as the hostname of the asset Will we be able to auto generate from source system','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('VIRTUAL_PLATFORM_LOCATION','Physical locations; a room number/name within a building. Rack number within a data centre or server room. Space- designated area within a room. Virtual Platform Host Locations; cluster, virtual machine id, container id Engineering does not own this information, hence an empty column will be exported.','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('SW_VENDOR','Use the offical vendor name as provided by the software documentation.','1');
