INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('MAINTENANCE_SUPPORT_SUPPLIER(HW)','Could be a vendor or 3rd party maintenance contract etc','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('HW_END_OF_SUPPORT','End of Service Life (EoSL) (for IT); End of Vendor Maintenance date (EoM) or End of service Life (EoL) (for Network)','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('HW_END_OF_LIFE','End of Service Life (EoSL) (for IT); End of Vendor Maintenance date (EoM) or End of service Life (EoL) (for Network)','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('DEPENDENT_HARDWARE','EXAMPLES - This is the hardware that is hosting the virtual machines - In the RAN scenario - lots of different cards linked to an overarching   hardware element','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('INSTANCE_TYPE','Appliance / Virtualised / Container/ Other / Router /switch / Firewall /stacked switch etc In the future we may be able to generate','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('OS_NAME','Operating system where the network node software is running (Linux distribution, Windows etc)','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('OS_SW_VERSION','Operating system version where the network node software is running (Linux distribution, Windows etc)','1');
