INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_DECOMMISSIONED_DATE','humanised data We need to understand the decommissioning process to understand if this can be generated, this should also identify any downstream processes that need to know the asset has been decommissioned - this includes supply chain','1');
