INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('SW_EEOSL_CONTRACT_DATE','End of Service Life (EoSL) (for IT); End of Vendor Maintenance date (EoM) or End of service Life (EoL) (for Network)','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('DEPENDANT_SYSTEM_SW','This is the software required to be in place to support the dependent hardware e.g. host virtualisation software (ESX, Docker etc)','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('RESILIENCE_MODEL',' (e.g. active /active, active/passive)','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('RESILIENCE_GEOGRAPHIC_SITE','e.g. automatic, manual, none, including Recovery, Time Objective (RTO) and Recovery Point Objective (RPO) ','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('RESILIENCE_LOCAL_SITE','e.g. automatic, manual, none, including Recovery, Time Objective (RTO) and Recovery Point Objective (RPO) ','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('DEPENDANT_PRODUCT_NAME','The list of products that rely on the asset to be delivered','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('BUSINESS_SERVICE_NAME','Product name or PECN description','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('CUSTOMER','What customer is this asset assigned to (where applicable)','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_PRIVILEGED_ACCESS_LOGGING','Does this asset record all instances of logging in with privileged access, either locally or within other applications','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('HW_COMPONENT_NAME','Describes the hardware component name','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('HW_COMPONENT_SUBTYPE','Describes the hardware component  subtype ','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('HW_COMPONENT_VERSION','Describes the hardware component  version number','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('EXPOSED EDGE FLAG','​Equipment that is either within customer premises, directly addressable from customer/user equipment, or is physically vulnerable. Physically vulnerable equipment includes equipment in road-side cabinets or attached to street furniture. The Exposed Edge includes CPEs, base station equipment, OLT equipment and MSAN/DSLAM equipment.','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('EXTERNAL FACING FLAG','An externally-facing system is any system with an externally-facing interface. An externally-facing interface is any system interface, on a Relevant Asset, which is accessible to people or systems outside of your direct control.','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('MANAGEMENT_PLANE','a system that configures, monitors, and provides management, monitoring and configuration services to, all layers of the network stack and other parts of the system','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('NETWORK_OVERSIGHT','Network oversight functions are the components of the network that oversee and control the security critical functions, which make them vitally important in overall network security. They are essential for the network provider to understand the network, secure the network, or to recover the network.','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('PECN FLAG','The PECN the asset supports refer to PECN classification tab Public Electronic Communications Network • an electronic communications network provided wholly or mainly for the purpose of making electronic communications services available to members of the public THIS FIELD MUST BE N/A IF THE ASSET IS NOT IN SCOPE OF TSR','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('PECS FLAG','The PECS the asset supports -Currently this will default to N/A as this analysis is yet to be completed Public Electronic Communications Service • any electronic communications service that is provided so as to be available for use by members of the public THIS FIELD MUST BE N/A IF THE ASSET IS NOT IN SCOPE OF TSR','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('SECURITY_CRITICAL_FUNCTION','1.3 A ‘security critical function’ in relation to a public electronic communications network or service means “any function of the network or service whose operation is likely to have a material impact on the proper operation of the entire network or service or a material part of it” (Regulation 2).​ 1.4 Security critical functions will therefore make up different proportions of networks or services, the specific details being dependent on the unique operating mode of each individual network. However, security critical functions will include a broad range of essential functions within the network that could impact its proper operation and not simply those whose primary function is security. The guidance in this code of practice sets out specific protections targeted at different functions of networks and services that may be considered critical. It does not seek to exhaustively define components as critical.​ 1.5 When deciding which functions of the network or service could not be considered as security critical, providers should be able to demonstrate that individual functions do not have a material impact on the proper operation of the entire network or service, or a material part of it.​','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('PRODUCT_IMPORTANCE','Strategic Assets • Strategic assets are key technological assets which are included in evolution and modernization plans and have direct impact on customer. • New assets always belong to this cluster and must always be on supported versions of HW and SW. Non-strategic assets (Legacy) • Assets that have no future strategic role and subject to a clear decommission/removal beyond one year • Assets that are key to the ongoing needs of the network but whose features are considered stable and whose feature roadmaps are not directly beneficial to Vodafone’s needs. Assets under decommissioning Assets under decommissioning are mainly legacy system where: • Decommissioning has already started but requires multi-year to be completed. • Decommissioning has been planned and will start within this fiscal year. • Already dismantled or partially dismantled. For this cluster no target is foreseen, but evidence of decommissioning plan is required.  • Legacy asset dismantled or for which decommissioning has already started but requires multi-year to be completed.','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('Business Critical','Vodafone’s information assets must be assessed for their importance to the business by the information asset owner. Assets falling within one or more of the following categories MUST be categorised as Critical Information Assets: A. Assets processing or storing personal data which have been identified as medium (or above) risk   assets through   the   risk profiling methodology in   the Personal   Data Processing Register (PDPR) Detailed Requirements [Reference17] B. Assets in scope of either the Payment Card Industry Data Security Standard (PCI-DSS) or Sarbanes-Oxley (Sox) compliance. C. Assets involved in the transport, processing, and storage of C3 Confidential or C4 Secret labelled data. D. Mission critical voice, data and supporting services for IT and network infrastructure which have been identified from business continuity / resilience programmes, or any Critical National Infrastructure. E. Systems and services which are directly accessible from the Internet. F. Security services and systems. G. SCF = Yes','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('CRITICALITY_TYPE','Vodafone’s information assets must be assessed for their importance to the business by the information asset owner. Assets falling within one or more of the following categories MUST be categorised as Critical Information Assets: A. Assets processing or storing personal data which have been identified as medium (or above) risk   assets through   the   risk profiling methodology in   the Personal   Data Processing Register (PDPR) Detailed Requirements [Reference17] B. Assets in scope of either the Payment Card Industry Data Security Standard (PCI-DSS) or Sarbanes-Oxley (Sox) compliance. C. Assets involved in the transport, processing, and storage of C3 Confidential or C4 Secret labelled data. D. Mission critical voice, data and supporting services for IT and network infrastructure which have been identified from business continuity / resilience programmes, or any Critical National Infrastructure. E. Systems and services which are directly accessible from the Internet. F. Security services and systems. G. SCF = Yes','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_SERIAL_NUMBER','The Serial number for the asset In the future we can get from an auto discovery, issue when we do not have auto discovery for the asset?','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('HW_PART_NUMBER','The specific part number for the asset we need to understand the opportunity for auto discovery and what we default to if asset does not have auto discovery Unknown','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('PLANNED_ACTION_DESCRIPTION','If there are any plans for next steps with an asset such as decommissioning/upgrading (where applicable) humanised data','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('IDENTIFIED_ACTION','Any action required on an asset e.g. replacement Humanised Data','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('LAST_UPGRADE_DATE','Last date the device was upgraded','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ME_ENVIRONMENT','Is this asset current in production or is it a LAB asset not currently live within the network (such as Lab devices)','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ORGANISATION_NAME','Which local market owns the asset in the future  - at network level we know if it’s a group or UK asset so could be automated','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('BUDGET_ESTIMATED','The estimated budget assigned to this specific asset where it is part of a larger project','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('BUNDLE_BUDGET','Budget of all the assets associated with a larger project','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('ASSURANCE_CALL','Unique ID assigned to the budget bundle as part of a larger project','1');
