INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('PROJECT_END_DATE','The expected end date of any project associated with this asset ','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('PROJECT_STATUS','Current Status of any associated project','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('SERVICE_LEVEL','What is the required service level (operational time) this asset is contracted to. E.g. Platinum, gold, Silver','1');
INSERT INTO GLOSSARYITEMS (HEADER,DESCRIPTION,ISTSRFIELD) VALUES('LAST_PENTEST_DATE','The date the asset was last Pen Tested','1');
